style.css:
@-moz-document url-prefix("https://chatgpt.com") {
/* Hide headers, sidebars, upgrade buttons, etc. */
  header, nav, [data-testid="sidebar"], [data-testid="user-menu-button"],
  [data-testid="upgrade-button"], [data-testid="user-avatar"], 
  .sticky, .px-3.pt-3, .border-t {
    display: none !important;
  }

  /* Side panel (mimics VS Code file tree) */
  [class*="sidebar"] {
    width: 240px !important;
    background-color: #252526 !important;
    position: fixed !important;
    top: 0;
    bottom: 0;
    left: 0;
    z-index: 999 !important;
    overflow: hidden !important;
    border-right: 1px solid #333 !important;
  }

  /* Main chat area */
  main, [class*="main"], [class*="scrollable"] {
    margin-left: 240px !important;
    background-color: #1e1e1e !important;
    padding: 16px !important;
    overflow-y: auto !important;
  }

  /* Message area */
  .markdown, .prose, .text-message, .group, [data-message-id] {
    background-color: #1e1e1e !important;
    border-left: 4px solid #007acc !important;
    padding: 10px !important;
    margin: 10px 0 !important;
    white-space: pre-wrap !important;
    font-family: 'Fira Code', 'Consolas', monospace !important;
    font-size: 13px !important;
    color: #d4d4d4 !important;
  }

  /* Input bar at bottom */
  form, textarea, input, button, [class*="composer"] {
    background-color: #1e1e1e !important;
    color: #d4d4d4 !important;
    font-family: 'Fira Code', monospace !important;
    font-size: 13px !important;
    border: none !important;
  }

  /* Optional: Remove new chat, profile & upgrades */
  [data-testid="new-chat-button"], [data-testid="user-avatar"], 
  .absolute.top-0, .flex-col.items-center {
    display: none !important;
  }

  /* Optional: VS Code-style top tab bar */
  body::before {
    content: "? chatgpt-session-1.json";
    display: block;
    background-color: #2d2d2d;
    color: #d4d4d4;
    padding: 8px 12px;
    font-family: 'Fira Code', monospace;
    font-size: 13px;
    border-bottom: 1px solid #333;
  }
}
